import json,os,subprocess as s,sys,tempfile,time
def k(*a,env=None,t=120):
    t0=time.time();p=s.run([sys.executable,'_tools/kbmon.py',*a],capture_output=True,text=True,env=env or os.environ,timeout=t);p.wall=time.time()-t0;return p
def fail(m):
