E=dict(os.environ,KB_COORD_TOOLS='1')
p=s.Popen([sys.executable,'_tools/kb_mcp.py'],stdin=s.PIPE,stdout=s.PIPE,stderr=s.DEVNULL,text=True,env=E)
def send(m):
    p.stdin.write(json.dumps(m)+'\n');p.stdin.flush()
send({'jsonrpc':'2.0','id':1,'method':'initialize','params':{'protocolVersion':'2025-06-18','capabilities':{},'clientInfo':{'name':'check','version':'0'}}})
