tools=None;t0=time.time()
while time.time()-t0<60 and tools is None:
    line=p.stdout.readline()
    if not line: break
    m=json.loads(line)
    if m.get('id')==2: tools=m.get('result',{}).get('tools',[])
p.kill()
desc=next((x.get('description','') for x in tools or [] if x.get('name')=='coord_post'),None)
if desc is None: fail('no coord_post tool')
if 'ask' not in desc or 'answer' not in desc: fail('coord_post does not list ask and answer')
u=s.run([sys.executable,'_tools/coord.py','--help'],capture_output=True,text=True).stdout
if 'ask' not in u or 'answer' not in u: fail('coord.py usage does not list ask and answer')
print('ok: coord_post and coord.py list ask and answer')

